do {
	struct dentry *dtmp;
	struct kernfs_node *kntmp;
	const char *name;
	char *name_copy;

	if (kn == knparent)
		return dentry;

	rcu_read_lock();
	kntmp = find_next_ancestor(kn, knparent);
	if (WARN_ON(!kntmp)) {
		rcu_read_unlock();
		dput(dentry);
		return ERR_PTR(-EINVAL);
	}
	name = kernfs_rcu_name(kntmp);
	name_copy = kstrdup(name, GFP_ATOMIC);
	rcu_read_unlock();

	if (!name_copy) {
		dput(dentry);
		return ERR_PTR(-ENOMEM);
	}

	dtmp = lookup_positive_unlocked(name_copy, dentry, strlen(name_copy));
	kfree(name_copy);
	dput(dentry);
	if (IS_ERR(dtmp))
		return dtmp;
	knparent = kntmp;
	dentry = dtmp;
} while (true);

